#!/usr/bin/env node
/**
 * tools/gen-des-db-index.mjs
 *
 * Generates a reverse index from js/des-db/weapons.js mapping each
 * upgrade_ref [base_weapon_id, path_id, level] → { category, id }.
 *
 * The generated file is written to js/des-db/idx-upgrade-ref.js and is
 * intended to enable O(1) lookup of which <category, id> an upgrade_ref
 * refers to.
 *
 * Usage:
 *   node tools/gen-des-db-index.mjs
 *
 * @ts-check
 */

import { rmSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const PROJECT_ROOT = path.resolve(__dirname, '..');
const DB_DIR = path.join(PROJECT_ROOT, 'js', 'des-db');
const WEAPONS_PATH = path.join(DB_DIR, 'weapons.js');
const OUTPUT_PATH = path.join(DB_DIR, 'idx-upgrade-ref.js');

// ---------------------------------------------------------------------------
// Load weapons data
// ---------------------------------------------------------------------------

/** @type {{ default: { items: Record<string, any> } }} */
const weaponsMod = await import(`file://${WEAPONS_PATH}`);
const items = weaponsMod.default.items;

// ---------------------------------------------------------------------------
// Build the index
// ---------------------------------------------------------------------------

/**
 * Build a key string from an upgrade_ref triple.
 * @param {[number, number | null, number | null]} ref
 * @returns {string}
 */
function refKey(ref) {
  return `${ref[0]}:${ref[1] ?? 'null'}:${ref[2] ?? 'null'}`;
}

/** @type {Record<string, { category: string, id: string }>} */
const index = {};
/** @type {Array<{ key: string, firstId: string, dupId: string }>} */
const duplicates = [];
let skipped = 0;

for (const [id, entry] of Object.entries(items)) {
  if (!Array.isArray(entry.upgrade_ref)) {
    skipped++;
    continue;
  }
  const key = refKey(entry.upgrade_ref);
  if (index[key]) {
    // Duplicate detected — record it so we can hard-fail below.
    duplicates.push({ key, firstId: index[key].id, dupId: id });
    continue;
  }
  index[key] = { category: 'weapons', id };
}

if (duplicates.length > 0) {
  console.error(
    `❌  ${duplicates.length} duplicate upgrade_ref tuple(s) detected:\n` +
      duplicates
        .map((d) => `   key "${d.key}" already mapped to ${d.firstId}, conflicts with ${d.dupId}`)
        .join('\n'),
  );
  process.exit(1);
}

const entryCount = Object.keys(index).length;

// ---------------------------------------------------------------------------
// Write output
// ---------------------------------------------------------------------------

// Clear any pre-existing generated file.
rmSync(OUTPUT_PATH, { force: true });

const header = [
  '/**',
  ' * ⚠️  GENERATED FILE — DO NOT EDIT.',
  ' *',
  ' * This file is automatically generated by tools/gen-des-db-index.mjs',
  ' * from the upgrade_ref fields in js/des-db/weapons.js.',
  ' * Any manual edits will be lost on regeneration.',
  ' *',
  ' * Regenerate:  node tools/gen-des-db-index.mjs',
  ' */',
].join('\n');

const meta = {
  // Deterministic timestamp: honour SOURCE_DATE_EPOCH for reproducible builds;
  // otherwise omit (undefined) so JSON.stringify drops the key entirely,
  // preventing spurious git diffs on every regeneration.
  generatedAt: process.env.SOURCE_DATE_EPOCH
    ? new Date(Number(process.env.SOURCE_DATE_EPOCH) * 1000).toISOString()
    : undefined,
  tool: 'tools/gen-des-db-index.mjs',
  source: 'js/des-db/weapons.js',
  schema:
    'Keyed by "base_weapon_id:path_id:level" where null components are ' +
    'serialized as "null". Each value is { category, id } where category ' +
    'is always "weapons" and id is the hex-ID string from weapons.js.',
  entryCount,
};

const json = JSON.stringify({ _meta: meta, index }, null, 2);
const content = `${header}\nexport default ${json};\n`;

writeFileSync(OUTPUT_PATH, content, 'utf8');

// ---------------------------------------------------------------------------
// Summary
// ---------------------------------------------------------------------------

const relOutput = path.relative(PROJECT_ROOT, OUTPUT_PATH);
console.log('des-db upgrade_ref index generated:');
console.log(`  Source:   js/des-db/weapons.js (${Object.keys(items).length} weapon entries)`);
console.log(`  Indexed:  ${entryCount} upgrade_ref tuples`);
console.log(`  Skipped:  ${skipped} weapon entries without upgrade_ref (arrows/bolts/ghosts/etc.)`);
console.log(`  Output:   ${relOutput}`);
